class Solution {
  public int splitArray(int[] nums, int k) {
    long lo = 0, hi = 0;
    for (int x : nums) {
      lo = Math.max(lo, x);
      hi += x;
    }
    // smallest cap that needs at most k pieces
    while (lo < hi) {
      long mid = (lo + hi) / 2;
      if (pieces(nums, mid) <= k) hi = mid;
      else lo = mid + 1;
    }
    return (int) lo;
  }

  private int pieces(int[] nums, long cap) {
    int count = 1;
    long sum = 0;
    for (int x : nums) {
      if (sum + x > cap) {
        count++;
        sum = 0;
      }
      sum += x;
    }
    return count;
  }
}
